package com.reg21meme.dross.boss.emberdactyl.trophy.client;

import com.reg21meme.dross.Dross;
import net.minecraft.resources.ResourceLocation;
import software.bernie.geckolib.core.animatable.GeoAnimatable;
import software.bernie.geckolib.model.GeoModel;

/**
 * The Emberdactyl trophy's files, all generated by {@code tools/fire/trophies.py}: the Emberdactyl's model with its
 * young's, its egg (whole and burst open), a miniature of its volcano, a pool of lava and two spires of rock beside it
 * (its own copies, {@code geo/block/emberdactyl_trophy.geo.json} for the placed trophy and
 * {@code geo/item/emberdactyl_trophy.geo.json} for the item: GeckoLib shares a model's bones between everything drawn
 * with it, so the bosses, the placed trophies and the items each get their own), the fifteen held poses
 * ({@code animations/block/emberdactyl_trophy}) and the trophy's own 1024 x 1024 textures (their texels side by side):
 * the solid parts, their glow and the death's magma cracks.
 */
public class EmberTrophyGeoModel<T extends GeoAnimatable> extends GeoModel<T>
{
    public static final ResourceLocation BLOCK_MODEL = new ResourceLocation(Dross.MODID, "geo/block/emberdactyl_trophy.geo.json");
    public static final ResourceLocation ITEM_MODEL = new ResourceLocation(Dross.MODID, "geo/item/emberdactyl_trophy.geo.json");
    public static final ResourceLocation ANIMATIONS = new ResourceLocation(Dross.MODID, "animations/block/emberdactyl_trophy.animation.json");
    /** The trophy's textures: the solid parts, their glow (lava, embers, eyes) and the death's magma cracks. */
    public static final ResourceLocation TEXTURE = texture("");
    public static final ResourceLocation GLOW = texture("_glow");
    public static final ResourceLocation CRACKS = texture("_cracks");

    private static ResourceLocation texture(String suffix)
    {
        return new ResourceLocation(Dross.MODID, "textures/block/emberdactyl_trophy/emberdactyl_trophy" + suffix + ".png");
    }

    private final ResourceLocation model;

    /** @param model {@link #BLOCK_MODEL} or {@link #ITEM_MODEL} */
    public EmberTrophyGeoModel(ResourceLocation model)
    {
        this.model = model;
    }

    @Override
    public ResourceLocation getModelResource(T animatable)
    {
        return this.model;
    }

    @Override
    public ResourceLocation getTextureResource(T animatable)
    {
        return TEXTURE;
    }

    @Override
    public ResourceLocation getAnimationResource(T animatable)
    {
        return ANIMATIONS;
    }
}
